class A {
    int calc(int x) { return x + 5; }
    int run(int x) { return calc(x) * 2; }
}

class B extends A {
    int calc(int x) { return x * 3; }
}

public class Main {
    public static void main(String[] args) {
        A obj = new B();
        System.out.print(obj.run(4));
    }
}

#include <stdio.h>

int f(int n) {
    if (n < 3) return n;
    return f(n - 1) + f(n - 3);
}

int main() {
    printf("%d", f(8));
    return 0;
}

